     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:12pt"&gt;Consulten los &lt;/span&gt;&lt;a class="Hyperlink SCXW259907531 BCX8" href="https://forecast.weather.gov/MapClick.php?CityName=Corvallis&amp;amp;state=OR&amp;amp;site=PQR&amp;amp;textField1=44.5647&amp;amp;textField2=-123.261&amp;amp;e=0" rel="noreferrer noopener" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; text-decoration-line: none;" target="_blank"&gt;&lt;span style="color:rgb(70, 120, 134); font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:12pt"&gt;pron&oacute;sticos oficiales de los niveles de los r&iacute;os del Servicio Meteorol&oacute;gico Nacional&lt;/span&gt;&lt;/a&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:12pt"&gt;.&lt;/span&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
