&lt;h2&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;strong&gt;Looking Ahead&lt;/strong&gt;&lt;span style="font-size:18pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h2&gt;
